// golden_test.go — T-45: the generated-golden differential for the
// vaultscan module's pure halves — the kind doors, the lock/curated
// predicates, the core-note law, the direct frontmatter parser (flow
// REPLACE, block tags, the 16k head cap), the CPython urlparse shapes,
// the fold laws, the sanitizer, the digest lines, the weighed-evidence
// scale and census, the absorption/bend/disk-spelling laws, the
// selection arithmetic, and the validation door on a real temp vault.
//
// testdata/vaultscan.golden.json is generated by
// testdiff/goldens/dump_vaultscan.py from the unmodified reference
// (assadigit/GitCurator @ 98f4fc7, the pinned venv's CPython 3.12.15
// stdlib) — no per-run facts inside: every temp-vault path is folded
// to '<vault>/…'.
//
// THE LAW: goldens are never hand-edited; a divergence is either a Go
// bug (fix the port) or a reference behavior change (regenerate + say
// so in the commit).
package vaultscan

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"

	"github.com/assadigit/second-brain-project/internal/chrometabs"
	"github.com/assadigit/second-brain-project/internal/helpers"
	"github.com/assadigit/second-brain-project/internal/notereads"
	"github.com/assadigit/second-brain-project/internal/storage"
)

var vsGolden map[string]any

func loadVSGolden(t *testing.T) map[string]any {
	t.Helper()
	if vsGolden != nil {
		return vsGolden
	}
	data, err := os.ReadFile("testdata/vaultscan.golden.json")
	if err != nil {
		t.Fatalf("golden file: %v", err)
	}
	var g map[string]any
	if err := json.Unmarshal(data, &g); err != nil {
		t.Fatalf("golden json: %v", err)
	}
	vsGolden = g
	return g
}

func vsSection(t *testing.T, name string) map[string]any {
	t.Helper()
	v, ok := loadVSGolden(t)[name].(map[string]any)
	if !ok {
		t.Fatalf("golden section %q missing or not an object", name)
	}
	return v
}

// cmpVSGolden compares through the canonical Python dumps (maps sort
// keys; slices keep order) so the comparison is byte-honest (the
// chrometabs pattern).
func cmpVSGolden(t *testing.T, what string, got, want any) {
	t.Helper()
	g := storage.PyDumps(normVS(got))
	w := storage.PyDumps(normVS(want))
	if g != w {
		t.Errorf("%s diverges from the reference golden:\n got: %s\nwant: %s",
			what, g, w)
	}
}

func normVS(v any) any {
	switch t := v.(type) {
	case string:
		return t
	case int:
		return float64(t)
	case int64:
		return float64(t)
	case bool, float64, nil:
		return t
	case json.Number:
		f, _ := t.Float64()
		return f
	case map[string]any:
		out := map[string]any{}
		for k, val := range t {
			out[k] = normVS(val)
		}
		return out
	case map[string]int:
		out := map[string]any{}
		for k, val := range t {
			out[k] = float64(val)
		}
		return out
	case []any:
		out := make([]any, len(t))
		for i, val := range t {
			out[i] = normVS(val)
		}
		return out
	case []string:
		out := make([]any, len(t))
		for i, s := range t {
			out[i] = s
		}
		return out
	default:
		return t
	}
}

// foldVault folds the temp vault root to '<vault>' (the generator's
// no-per-run-facts law).
func foldVault(t *testing.T, vault, s string) string {
	t.Helper()
	return strings.ReplaceAll(s, vault, "<vault>")
}

// rowMap renders a NoteRow as the reference's row dict.
func rowMap(t *testing.T, vault string, n *NoteRow) map[string]any {
	return map[string]any{
		"file":             n.File,
		"path":             foldVault(t, vault, n.Path),
		"rel":              n.Rel,
		"title":            n.Title,
		"source":           n.Source,
		"domain":           n.Domain,
		"category":         n.Category,
		"subcategory":      n.Subcategory,
		"tags":             tagsAny(n.Tags),
		"fetch_status":     n.FetchStatus,
		"app_owned":        n.AppOwned,
		"folder":           n.Folder,
		"in_root":          n.InRoot,
		"core":             n.Core,
		"locked":           n.Locked,
		"curated":          n.Curated,
		"stars":            n.Stars,
		"primary_language": n.PrimaryLang,
		"org":              n.Org,
		"protected":        n.Protected,
	}
}

func tagsAny(tags []string) []any {
	out := make([]any, 0, len(tags))
	for _, t := range tags {
		out = append(out, t)
	}
	return out
}

// --- 1. the kind doors --------------------------------------------------

func TestGoldenKindDoors(t *testing.T) {
	sec := vsSection(t, "kind_doors")
	cmpVSGolden(t, "kind_doors.repos_kind",
		[]any{
			isReposKind("repos"), isReposKind("REPOS"),
			isReposKind(" Repos "), isReposKind("websites"),
			isReposKind(""), isReposKind(""),
		},
		sec["repos_kind"])
	labels := map[string]any{}
	for _, k := range []string{"'repos'", "'websites'", "None"} {
		v := ""
		switch k {
		case "'repos'":
			v = "repos"
		case "'websites'":
			v = "websites"
		}
		labels[k] = kindLabel(v)
	}
	cmpVSGolden(t, "kind_doors.labels", labels, sec["labels"])
	protected := map[string]any{
		"repos":    protectedFoldersFor("repos"),
		"websites": protectedFoldersFor("websites"),
		"junk":     protectedFoldersFor("junk"),
	}
	cmpVSGolden(t, "kind_doors.protected", protected, sec["protected"])
}

// --- 2. the predicates --------------------------------------------------

func TestGoldenPredicates(t *testing.T) {
	sec := vsSection(t, "predicates")
	truthyVals := []string{"true", "True", "TRUE", `"true"`, " yes ",
		"'1'", "1", "false", "no", "0", "", "maybe"}
	tr := map[string]any{}
	for _, v := range truthyVals {
		tr[helpers.PyRepr(v)] = truthy(v)
	}
	tr["None"] = false // repr(None) — str(None or '') == ''
	cmpVSGolden(t, "predicates.truthy", tr, sec["truthy"])

	meta := []string{"true", "yes", "1", `"true"`, "false", ""}
	lm := map[string]any{}
	for _, v := range meta {
		lm[helpers.PyRepr(v)] = noteLocked(&notereads.Inventory{
			Locked: truthy(v)})
	}
	lm["None"] = noteLocked(&notereads.Inventory{})
	cmpVSGolden(t, "predicates.locked.meta", lm,
		sec["locked"].(map[string]any)["meta"])
	cl := map[string]any{
		"'true'":  noteLocked(&notereads.Inventory{CategoryLocked: true}),
		"'false'": noteLocked(&notereads.Inventory{CategoryLocked: false}),
	}
	cmpVSGolden(t, "predicates.locked.cat_locked", cl,
		sec["locked"].(map[string]any)["cat_locked"])
	tags := []string{"lock", "Lock", "LOCK", "locked", "Locked",
		"notelock", "design"}
	tg := map[string]any{}
	for _, tag := range tags {
		tg[tag] = noteLocked(&notereads.Inventory{
			Tags: []string{tag, "design"}})
	}
	cmpVSGolden(t, "predicates.locked.tags", tg,
		sec["locked"].(map[string]any)["tags"])
	cmpVSGolden(t, "predicates.locked.junk",
		[]any{
			noteLocked(nil), noteLocked(nil), noteLocked(&notereads.Inventory{}),
			noteLocked(&notereads.Inventory{}),
			noteLocked(&notereads.Inventory{CategoryLocked: true}),
		},
		sec["locked"].(map[string]any)["junk"])

	curatedMeta := []string{"true", "yes", "1", "false", ""}
	cm := map[string]any{}
	for _, v := range curatedMeta {
		cm[helpers.PyRepr(v)] = noteCurated(&notereads.Inventory{
			Curated: truthy(v)})
	}
	cm["None"] = noteCurated(&notereads.Inventory{})
	cmpVSGolden(t, "predicates.curated.meta", cm,
		sec["curated"].(map[string]any)["meta"])
	ct := map[string]any{}
	for _, tag := range []string{"curated", "Curated", "CURATED",
		"curated-ish"} {
		ct[tag] = noteCurated(&notereads.Inventory{Tags: []string{tag}})
	}
	cmpVSGolden(t, "predicates.curated.tags", ct,
		sec["curated"].(map[string]any)["tags"])
	cmpVSGolden(t, "predicates.curated.junk",
		[]any{
			noteCurated(nil), noteCurated(&notereads.Inventory{}),
			noteCurated(&notereads.Inventory{Locked: true}),
		},
		sec["curated"].(map[string]any)["junk"])
	cmpVSGolden(t, "predicates.curated.independent",
		[]any{
			noteLocked(&notereads.Inventory{Curated: true}),
			noteCurated(&notereads.Inventory{Locked: true}),
		},
		sec["curated"].(map[string]any)["independent"])
}

// pyVal mirrors the reference's val-or-None table entries: the string
// "None" stands for the None value (str(None or ”) == ”).
func pyVal(v string) string {
	if v == "None" {
		return ""
	}
	return v
}

