// --- 4. the direct frontmatter parser -----------------------------------

func TestGoldenFrontmatter(t *testing.T) {
	sec := vsSection(t, "frontmatter")
	dir := t.TempDir()
	fmNote := func(name, text string) string {
		p := filepath.Join(dir, name)
		if err := os.WriteFile(p, []byte(text), 0o644); err != nil {
			t.Fatal(err)
		}
		return p
	}
	plain := parseNoteFrontmatter(fmNote("plain.md",
		"---\nsource: \"https://a.example/1\"\ntags: [b, \"c d\"]\n"+
			"category: X\ncategory: Y\nsubcategory: \"S\"\nkind: note\n"+
			"fetch_status: full\nmanaged_by: gitcurator\n"+
			"primary_language: Rust\norg: acme\nstars: 4200\n---\n\n# n\n"))
	cases := map[string]any{
		"plain": map[string]any{
			"source":           plain.Source,
			"tags":             tagsAny(plain.Tags),
			"category":         plain.Category,
			"subcategory":      plain.Subcategory,
			"kind":             plain.Kind,
			"fetch_status":     plain.FetchStatus,
			"managed_by":       plain.ManagedBy,
			"primary_language": plain.PrimaryLanguage,
			"org":              plain.Org,
			"stars":            plain.Stars,
			"locked":           plain.Locked,
			"category_locked":  plain.CategoryLocked,
			"curated":          plain.Curated,
		},
		"flow_replace": tagsAny(parseNoteFrontmatter(fmNote("flow.md",
			"---\ntags: [a]\ntags: [b]\n---\n\n# n\n")).Tags),
		"block_tags": tagsAny(parseNoteFrontmatter(fmNote("block.md",
			"---\ntags:\n  - one\n  - \"two three\"\n  - 'four'\n"+
				"---\n\n# n\n")).Tags),
		"lock_doors": map[string]any{
			"locked": parseNoteFrontmatter(fmNote("lock-locked.md",
				"---\nlocked: true\n---\n\n# n\n")).Locked,
			"category_locked": parseNoteFrontmatter(
				fmNote("lock-category_locked.md",
					"---\ncategory_locked: true\n---\n\n# n\n")).CategoryLocked,
			"curated": parseNoteFrontmatter(fmNote("lock-curated.md",
				"---\ncurated: true\n---\n\n# n\n")).Curated,
		},
		"no_frontmatter": map[string]any{
			"source": parseNoteFrontmatter(fmNote("plain2.md",
				"# the owner's own note\n")).Source,
		},
		"empty": map[string]any{
			"source": parseNoteFrontmatter(
				filepath.Join(dir, "nope.md")).Source,
			"tags": tagsAny(parseNoteFrontmatter(filepath.Join(dir, "nope.md")).Tags),
		},
		"head_cap": map[string]any{
			"source": parseNoteFrontmatter(fmNote("big.md",
				"---\nsource: \"https://a.example/big\"\ntags: [x]\n"+
					"category: \"\"\nsubcategory: \"\"\n"+
					"managed_by: \"gitcurator\"\n"+
					"fetch_status: \"full\"\n---\n\n# Big\n\n"+
					strings.Repeat("body text\n", 6000))).Source,
			"managed_by": parseNoteFrontmatter(fmNote("big.md",
				"---\nsource: \"https://a.example/big\"\ntags: [x]\n"+
					"category: \"\"\nsubcategory: \"\"\n"+
					"managed_by: \"gitcurator\"\n"+
					"fetch_status: \"full\"\n---\n\n# Big\n\n"+
					strings.Repeat("body text\n", 6000))).ManagedBy,
		},
	}
	// the no-frontmatter and empty cases: the reference dumps the FULL
	// dicts; render them the same way
	nf := parseNoteFrontmatter(fmNote("plain2.md", "# the owner's own note\n"))
	cases["no_frontmatter"] = fmMap(nf)
	emp := parseNoteFrontmatter(filepath.Join(dir, "nope.md"))
	cases["empty"] = fmMap(emp)
	big := parseNoteFrontmatter(fmNote("big.md",
		"---\nsource: \"https://a.example/big\"\ntags: [x]\n"+
			"category: \"\"\nsubcategory: \"\"\n"+
			"managed_by: \"gitcurator\"\n"+
			"fetch_status: \"full\"\n---\n\n# Big\n\n"+
			strings.Repeat("body text\n", 6000)))
	cases["head_cap"] = fmMap(big)
	cmpVSGolden(t, "frontmatter", cases, sec)
}

func fmMap(fm notereads.Inventory) map[string]any {
	return map[string]any{
		"source":           fm.Source,
		"tags":             tagsAny(fm.Tags),
		"category":         fm.Category,
		"subcategory":      fm.Subcategory,
		"managed_by":       fm.ManagedBy,
		"kind":             fm.Kind,
		"fetch_status":     fm.FetchStatus,
		"primary_language": fm.PrimaryLanguage,
		"org":              fm.Org,
		"stars":            fm.Stars,
		"locked":           fm.Locked,
		"category_locked":  fm.CategoryLocked,
		"curated":          fm.Curated,
	}
}

// --- 5. the urlparse shapes ---------------------------------------------

func TestGoldenPyURL(t *testing.T) {
	sec := vsSection(t, "pyurl")
	probes := []string{
		"https://a.example/x", "https://A.example:8080/X;param?q#f",
		"http://a.example/x", "https://a.example", "https://a.example/",
		"https://a.example?q", "https://a.example#f",
		"https://a.example/p/;q", "https://a.example/x;param",
		"https://a\tb.com/x", "https://[x/y", "https://a.example//",
		"not a url",
	}
	// netloc mirrors the reference's urlparse(url).netloc or '<raise>':
	// the \t\r\n removal, the case-insensitive scheme, the netloc
	// between "//" and the first of "/?#" (case preserved), the
	// bracket law's raise.
	netlocs := map[string]any{}
	paths := map[string]any{}
	for _, u := range probes {
		stripped := strings.Map(func(r rune) rune {
			if r == '\t' || r == '\r' || r == '\n' {
				return -1
			}
			return r
		}, u)
		key := helpers.PyRepr(u)
		low := strings.ToLower(stripped)
		isHTTP := strings.HasPrefix(low, "https://") ||
			strings.HasPrefix(low, "http://")
		if !isHTTP {
			netlocs[key] = "" // no scheme → urlparse's netloc is ''
			paths[key] = stripped
			continue
		}
		rest := ""
		if strings.HasPrefix(low, "https://") {
			rest = stripped[len("https://"):]
		} else {
			rest = stripped[len("http://"):]
		}
		netloc := rest
		if i := strings.IndexAny(netloc, "/?#"); i >= 0 {
			netloc = netloc[:i]
		}
		if !chrometabs.ValidPyNetloc(netloc) {
			netlocs[key] = "<raise>"
			paths[key] = "<raise>"
			continue
		}
		netlocs[key] = pyURLParseNetloc(u)
		paths[key] = pyURLParsePath(u)
	}
	cmpVSGolden(t, "pyurl.netloc", netlocs, sec["netloc"])
	cmpVSGolden(t, "pyurl.path", paths, sec["path"])
}

