func homesAny(homes []WeighedHome) []any {
	out := make([]any, 0, len(homes))
	for _, h := range homes {
		out = append(out, map[string]any{
			"folder": h.Folder, "weight": h.Weight, "reasons": strSlice(h.Reasons),
		})
	}
	return out
}

func strSlice(s []string) []any {
	out := make([]any, 0, len(s))
	for _, v := range s {
		out = append(out, v)
	}
	return out
}

