func TestGoldenAbsorb(t *testing.T) {
	sec := vsSection(t, "absorb")
	existing := []string{"Design/Color_Tools", "Design/Color_Palettes",
		"Design/Web_Workers", "AI/Agents", "AI/Chatbots"}
	hitOrNil := func(hit string) any {
		if hit == "" {
			return nil // the reference's None for no-hit
		}
		return hit
	}
	cmpVSGolden(t, "absorb", map[string]any{
		"exact":      hitOrNil(AbsorbNearDuplicate("Design/color tools", existing)),
		"exact_case": hitOrNil(AbsorbNearDuplicate("Design/Color_Tools", existing)),
		"sibling":    hitOrNil(AbsorbNearDuplicate("Design/Palettes", existing)),
		"short_leaf": hitOrNil(AbsorbNearDuplicate("Design/Web", existing)),
		"missing":    hitOrNil(AbsorbNearDuplicate("Design/Mockups", existing)),
		"no_parent":  hitOrNil(AbsorbNearDuplicate("Palettes", existing)),
		"tree_roots": sortedAny(TreeRoots(map[string]bool{
			"A/B/C": true, "X/Y": true, "Z": true})),
	}, sec)
}

func sortedAny(m map[string]bool) []any {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return strSlice(out)
}

