func TestGoldenBendAndDiskSpell(t *testing.T) {
	bendSec := vsSection(t, "bend")
	vault := t.TempDir()
	if err := os.MkdirAll(filepath.Join(vault, "Design", "Palettes"),
		0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(vault, "Design", "Palettes",
		"Name.md"), []byte("resident\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	planned := map[string]bool{}
	b1 := BendPath(filepath.Join(vault, "Design", "Palettes", "Name.md"),
		planned)
	planned[b1] = true
	b2 := BendPath(filepath.Join(vault, "Design", "Palettes", "Name.md"),
		planned)
	planned[b2] = true
	free := BendPath(filepath.Join(vault, "Design", "Palettes",
		"Fresh.md"), planned)
	cmpVSGolden(t, "bend", map[string]any{
		"first":  foldVault(t, vault, b1),
		"second": foldVault(t, vault, b2),
		"free":   foldVault(t, vault, free),
	}, bendSec)

	diskSec := vsSection(t, "disk_spell")
	if err := os.MkdirAll(filepath.Join(vault, "AI-Domain", "Agents"),
		0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Join(vault, "Design",
		"Assets & Resources"), 0o755); err != nil {
		t.Fatal(err)
	}
	memo := map[string]*string{}
	r1 := ResolveDiskFolder(vault, "AI-Domain/Agents", memo)
	r2 := ResolveDiskFolder(vault, "ai-domain/agents", memo)
	r3 := ResolveDiskFolder(vault, "Design/Assets__Resources", memo)
	r4 := ResolveDiskFolder(vault, "Design/Missing", memo)
	memoOut := map[string]any{}
	for k, v := range memo {
		if v == nil {
			memoOut[k] = nil
		} else {
			memoOut[k] = *v
		}
	}
	cmpVSGolden(t, "disk_spell", map[string]any{
		"exact":         deref(r1),
		"folded":        deref(r2),
		"safe_filename": deref(r3),
		"miss":          derefOrNil(r4),
		"memo":          memoOut,
		"walk":          DiskSpelling(vault, "AI-Domain/Agents"),
		"drift":         DiskSpelling(vault, "ai-domain/agents"),
		"gone":          DiskSpelling(vault, "Nope/Nada"),
	}, diskSec)
}

func deref(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

func derefOrNil(s *string) any {
	if s == nil {
		return nil
	}
	return *s
}

