func TestGoldenSelection(t *testing.T) {
	sec := vsSection(t, "selection")
	selNone := NormalizeSelection(nil)
	nillable := func(m map[string]bool) any {
		if m == nil {
			return nil
		}
		return m
	}
	cmpVSGolden(t, "selection.none", map[string]any{
		"deletions":      nillable(selNone.Deletions),
		"consolidations": nillable(selNone.Consolidations),
		"new_folders":    nillable(selNone.NewFolders),
		"moves":          nillable(selNone.Moves),
	}, sec["none"])
	cmpVSGolden(t, "selection.whole",
		PickedCounts(&pickPlan, selNone), sec["whole"])
	selPartial := NormalizeSelection(map[string][]string{
		"deletions":      {"https://b.example/2"},
		"new_folders":    {"Z/W"},
		"moves":          {"/v/m2.md"},
		"consolidations": {"/v/k2.md"},
	})
	cmpVSGolden(t, "selection.partial",
		PickedCounts(&pickPlan, selPartial), sec["partial"])
	selEmpty := NormalizeSelection(map[string][]string{
		"deletions": {}, "moves": {}, "new_folders": {},
		"consolidations": {}})
	cmpVSGolden(t, "selection.empty",
		PickedCounts(&pickPlan, selEmpty), sec["empty"])
	// the junk shapes (None, 'x', 42, [], wrong-typed sections) are
	// type-impossible in the Go door — every one reads as its
	// section's nil (the whole plan), the reference's own verdict.
	junkOut := make([]any, 0, 6)
	for i := 0; i < 6; i++ {
		junkOut = append(junkOut, PickedCounts(&pickPlan, Selection{}))
	}
	cmpVSGolden(t, "selection.junk", junkOut, sec["junk"])
	shapeJunk := NormalizeSelection(nil) // the Go shape has no junk
	// input: a non-dict reads as every-section-None (the reference's
	// junk law); the Go door's nil map is the same law.
	cmpVSGolden(t, "selection.shape_junk", map[string]any{
		"deletions":      nillable(shapeJunk.Deletions),
		"consolidations": nillable(shapeJunk.Consolidations),
		"new_folders":    nillable(shapeJunk.NewFolders),
		"moves":          nillable(shapeJunk.Moves),
	}, sec["shape_junk"])
}

