func TestGoldenValidate(t *testing.T) {
	sec := vsSection(t, "validate")
	c := newScanCase(t)
	c.note("Design/Palettes/resident.md", "https://settled.example/x")
	c.note("Design/Palettes/other.md", "https://settled.example/y")
	c.note("Same.md", "https://orphan.example/y",
		withCategory("Design"), withSubcategory("Palettes"))
	c.note("plain.md", "https://p.example/1")
	inv := ScanVaultInventory(c.vault, nil, nil, nil, VaultKindWebsites)
	rows := MoveCandidates(&inv, 40)
	byPath := map[string]*NoteRow{}
	for i := range inv.Notes {
		byPath[inv.Notes[i].Path] = &inv.Notes[i]
	}
	cands := make([]*NoteRow, 0, len(rows))
	exclude := map[string]bool{}
	for _, m := range rows {
		cands = append(cands, byPath[m.Path])
		exclude[m.Path] = true
	}
	data := LLMProposal{
		NewFolders: []string{"Design/Palette_Tools",
			"Design/Palettes", "Bare_Root", "../escape",
			"Nowhere/Orphan", "Design/color tools"},
		Moves: []RawMove{
			{Note: "Same.md", To: "Design/Palettes", Reason: "declared"},
			{Note: "Same.md", To: "Design/Palette_Tools", Reason: "dup"},
			{Note: "plain.md", To: "Design/Palettes", Reason: "fits",
				Confidence: "high"},
			{Note: "plain.md", To: "Design/Palettes", Reason: "again"},
			{Note: "Not Listed.md", To: "Design/Palettes", Reason: "no"},
			{Note: "Same.md", To: "AI-Domain/Agents",
				Reason: "stale key", Confidence: "low"},
		},
	}
	withHomes := AttachWeighedHomes(cands, &inv, exclude, nil, 40,
		VaultKindWebsites)
	candsHomes := map[string]any{}
	for _, cand := range cands {
		candsHomes[cand.File] = homesAny(cand.Homes)
	}
	moves, newFolders := ValidateMoves(data, cands, &inv, nil, nil,
		c.vault, VaultKindWebsites)
	movesOut := make([]any, 0, len(moves))
	for _, m := range moves {
		movesOut = append(movesOut, map[string]any{
			"note":           m.Note,
			"path":           foldVault(t, c.vault, m.Path),
			"title":          m.Title,
			"from":           m.From,
			"to":             m.To,
			"as":             m.As,
			"reason":         m.Reason,
			"low_confidence": m.LowConfidence,
		})
	}
	cmpVSGolden(t, "validate", map[string]any{
		"with_homes":  withHomes,
		"cands_homes": candsHomes,
		"moves":       movesOut,
		"new_folders": newFolders,
	}, sec)
}

